/*
 * A040244  Continued fraction for sqrt(261).
 * https://oeis.org/A040244
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy
 * Formula:   a(0) = ⌊√261⌋ = 16. For n ≥ 1 the terms are the periodic part of
 *            the continued fraction expansion of √261. They are generated by
 *            the standard recurrence: m₀ = 0, d₀ = 1, a₀ = ⌊√261⌋ = 16
 *            m_{k+1} = d_k·a_k – m_k d_{k+1} = (261 – m_{k+1}²) / d_k a_{k+1}
 *            = ⌊(a₀ + m_{k+1}) / d_{k+1}⌋ The sequence a(n...
 * Range:     u8 n <= 1, u16 n <= 89, u32 n <= 89, u64 n <= 89, u128 n <= 89,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* a0 = floor(sqrt(261)) */
    const seq_t a0 = 16;
    /* constant D for sqrt(261) */
    const seq_t D  = 261;

    if (n == 0) return a0;

    seq_t m = 0;    /* m_0 */
    seq_t d = 1;    /* d_0 */
    seq_t a_cur = a0;   /* a_0 */

    for (idx_t i = 1; i <= n; ++i) {
        seq_t m_next = d * a_cur - m;
        seq_t d_next = (D - m_next * m_next) / d;
        seq_t a_next = (a0 + m_next) / d_next;

        m = m_next;
        d = d_next;
        a_cur = a_next;
    }
    return a_cur;
}
